/** Events */
export const events = {
	binariesChanged: makeEvent<BinariesChanged>("binaries-changed"),
	configChanged: makeEvent<ConfigChanged>("config-changed"),
	prStatusChanged: makeEvent<PrStatusChanged>("pr-status-changed"),
	quitRequested: makeEvent<QuitRequested>("quit-requested"),
	scriptRunChanged: makeEvent<ScriptRunChanged>("script-run-changed"),
	sessionLifecycle: makeEvent<SessionLifecycle>("session-lifecycle"),
	thoughtsIndexUpdated: makeEvent<ThoughtsIndexUpdated>("thoughts-index-updated"),
	worktreeChanged: makeEvent<WorktreeChanged>("worktree-changed"),
};

/* Types */
/**
 *  View returned by [`list_active_sessions`]: one live session joined to its
 *  workstream's display name and project path.
 */
export type ActiveSessionView = {
	session: Session,
	workstreamTitle: string,
	projectPath: string,
};

/**
 *  Typed response for `hyprlayer ai status --json`.
 * 
 *  The CLI emits additional fields (location, version, …) that we don't need
 *  yet; they are captured by `#[serde(default)]` and ignored.
 */
export type AiStatus = {
	/**  The agent tool name as reported by the CLI, e.g. `"Claude Code"`. */
	agentTool?: string | null,
	/**  Whether the agent tool is installed and ready to use. */
	installed?: boolean,
	/**  Filesystem path to the agent binary, when installed. */
	location?: string | null,
};

/**
 *  Error shape every IPC command returns. The frontend renders `message`,
 *  shows `remedy` as the call-to-action, and may branch on `code`.
 */
export type AppError = {
	code: string,
	message: string,
	remedy: string | null,
};

export type AppSettings = {
	binaryOverrides?: Partial<{ [key in BinaryKind]: string }>,
	/**  Where work-item worktrees live; default ~/hyprlayer/worktrees. */
	worktreeRoot?: string | null,
	/**  Where app-owned project clones live; default ~/hyprlayer/repos. */
	reposRoot?: string | null,
	/**  Git behaviour for worktree creation, archive, and merge. */
	git?: GitSettings,
	/**  Keyboard-shortcut overrides for app operations. */
	keybindings?: KeybindingSettings,
	/**  The prompt library: built-in prompt overrides + custom prompts. */
	prompts?: PromptSettings,
	/**  Per-provider defaults (default model, etc.). Surfaced in Settings → Models. */
	providers?: ProviderSettings,
	/**  OS-toast behaviour when a session transitions to "needs you". */
	notifications?: NotificationSettings,
	/**  Whether quitting asks first. Settings → General. */
	quit?: QuitSettings,
	/**  Auto-generated agent tab titles (enable + which model). Settings → General. */
	tabTitles?: TabTitleSettings,
	/**
	 *  Multiplexer mode — run agents as native CLIs in persistent PTYs. Off by
	 *  default; with it off the app behaves exactly as before. Settings → Advanced.
	 */
	multiplexer?: MultiplexerSettings,
	/**
	 *  Developer tools (web inspector, PTY byte log, IPC trace). A Settings →
	 *  Advanced sibling row; reserved/off by default — nothing consumes it yet
	 *  (a stub like [`CodexSettings`], so the row can render and gain behaviour
	 *  later without a settings migration).
	 */
	devTools?: boolean,
	/**
	 *  The user dismissed the Full Disk Access explainer. macOS can't prompt for
	 *  that grant, so the notice is the only way to surface it — but once waved
	 *  off it stays off.
	 */
	fullDiskAccessNoticeDismissed?: boolean,
};

/**
 *  Report returned by [`cleanup_archived_workstreams`]: rows successfully
 *  deleted vs. rows that failed (logged individually as warnings).
 */
export type ArchiveCleanupReport = {
	deleted: number,
	failed: number,
};

/**
 *  View shape for the archive history view. `archive_exists` flags rows
 *  whose backup directory was deleted out-of-band (restore would fail; UI
 *  surfaces "delete permanently" as the only action).
 */
export type ArchivedWorkstreamView = {
	item: Workstream,
	/**  `<project>/archived-contexts/<slug>` — the on-disk backup path. */
	archivePath: string,
	archiveExists: boolean,
};

/**  Where a document lives within its root's layout. */
export type Area = 
/**  `<repos|global>/<…>/<user>/…` — a specific user's documents. */
{ kind: "user"; name: string } | 
/**  `<repos|global>/<…>/shared/…`. */
{ kind: "shared" } | 
/**  Anything outside the repos/global layout. */
{ kind: "other" };

/**  Binary statuses were re-probed (override set, redetect requested). */
export type BinariesChanged = null;

export type BinaryKind = "hyprlayer" | "claude" | "opencode" | "codex" | "gh" | "git" | "ollama";

export type BinaryState = { state: "ok" } | { state: "missing" } | { state: "tooOld"; min: string };

export type BinaryStatus = {
	kind: BinaryKind,
	name: string,
	path: string | null,
	version: string | null,
	state: BinaryState,
	optional: boolean,
	overridden: boolean,
};

export type Bootstrap = {
	config: ConfigSummary,
	projects: Project[],
	binaries: BinaryStatus[],
	settings: AppSettings,
	/**  Stock built-in prompt bodies (see [`PromptDefaults`]). */
	promptDefaults: PromptDefaults,
};

export type CatalogModel = {
	id: string,
	name: string,
};

export type CatalogProvider = {
	id: string,
	name: string,
	/**
	 *  Env var names the provider's API key maps to (e.g. `["ANTHROPIC_API_KEY"]`).
	 *  An empty list usually signals an OAuth-only provider.
	 */
	env: string[],
	doc: string | null,
	models: CatalogModel[],
};

export type CheckStatus = "pass" | "warn" | "fail";

/**  The rolled-up state of the PR's CI checks, derived from `statusCheckRollup`. */
export type ChecksState = 
/**  No checks configured/reported for the head commit. */
"none" | 
/**  At least one check still queued or running. */
"pending" | 
/**  Every check completed successfully (or neutral/skipped). */
"passing" | 
/**  At least one check failed, errored, or timed out. */
"failing";

export type ClaudeAuthStatus = {
	connected: boolean,
	provider: string | null,
	plan: string | null,
	org: string | null,
	account: string | null,
};

/**  One selectable model, as the CLI's own picker sees it. */
export type ClaudeModel = {
	/**
	 *  The `--model` value, or `None` for the "default" row (which launches with
	 *  no `--model` at all). Mirrors `ModelOption.flag` on the frontend.
	 */
	flag: string | null,
	/**
	 *  Canonical id the row resolves to, e.g. `claude-opus-5[1m]`. Keys the
	 *  Models-API context-window lookup once the `[1m]` suffix is stripped.
	 */
	resolvedModel: string | null,
	/**  Picker label, e.g. `Opus (1M context)`. */
	displayName: string,
	description: string | null,
	/**
	 *  Effort tiers this model accepts. Empty means it takes no `--effort` at
	 *  all (Haiku), which is different from "we don't know".
	 */
	supportedEffortLevels: string[],
	supportsFastMode: boolean,
	/**  Listed but not selectable — org policy can restrict a model. */
	disabled: boolean,
};

/**  The CLI's selectable model catalog. */
export type ClaudeProbe = {
	/**
	 *  Empty only if the CLI answered with an empty catalog; a probe that could
	 *  not run at all is an `Err`, so the two stay distinguishable.
	 */
	models: ClaudeModel[],
};

/**  Claude provider defaults. */
export type ClaudeSettings = {
	/**
	 *  Default model key for new sessions — one of the composer's model keys
	 *  (e.g. `"opus"`, `"sonnet"`) or a custom `--model` value. `None` keeps
	 *  the built-in default (Opus).
	 */
	defaultModel?: string | null,
	/**
	 *  Default reasoning-effort key for new sessions (`low`..`max`). `None`
	 *  keeps the built-in default (High).
	 */
	defaultEffort?: string | null,
	/**
	 *  Model key for the Commit/Ship/Revise action agents when the default
	 *  harness is Claude — cheaper than the chat default since these stages are
	 *  mechanical git/PR plumbing. `None` ⇒ `"sonnet"`.
	 */
	commitModel?: string | null,
	/**
	 *  Reasoning-effort key for the Commit/Ship/Revise action agents (Claude).
	 *  `None` ⇒ `"medium"`.
	 */
	commitEffort?: string | null,
	/**  Start new sessions in plan permission mode (`--permission-mode plan`). */
	defaultPlanMode?: boolean,
	/**
	 *  Which model keys appear in the composer's picker. `None` shows the
	 *  whole catalog (the CLI's live list when it resolves, else the built-in
	 *  presets, minus org-disabled rows); `Some(list)` shows exactly those keys
	 *  (presets plus any custom model ids the user added).
	 */
	visibleModels?: string[] | null,
	/**
	 *  Model keys the picker had already offered the last time it was open —
	 *  the watermark that lets a new model be added to a CURATED
	 *  [`Self::visible_models`] without resurrecting one the user removed on
	 *  purpose. `None` on an install that predates the check; the frontend then
	 *  seeds it from a frozen snapshot of the pre-catalog preset list.
	 */
	seenModelKeys?: string[] | null,
	/**
	 *  How `claude` authenticates: `"cli"` (subscription/login, the default and
	 *  historical behaviour — the spawned process inherits the user's env and
	 *  `~/.claude` state) or `"apiKey"` (enterprise — the app injects an API key
	 *  into the spawn env). `None`/absent is treated as `"cli"`.
	 */
	authMode?: string | null,
	/**
	 *  Anthropic API key, injected as `ANTHROPIC_API_KEY` at spawn when
	 *  `auth_mode == "apiKey"`. Stored in plaintext settings.json (see module
	 *  note); empty/`None` means "no key set".
	 */
	apiKey?: string | null,
	/**  Override the API endpoint (`ANTHROPIC_BASE_URL`) for a proxy/gateway. */
	baseUrl?: string | null,
	/**  Route through Amazon Bedrock (`CLAUDE_CODE_USE_BEDROCK=1`). */
	useBedrock?: boolean,
	/**  Route through Google Vertex (`CLAUDE_CODE_USE_VERTEX=1`). */
	useVertex?: boolean,
	/**
	 *  Enable the "Claude in Chrome" browser-control feature — adds `--chrome`
	 *  at spawn so sessions can drive the connected Chrome extension.
	 */
	chromeEnabled?: boolean,
	/**  Default model for in-app code reviews. Reserved — no review feature yet. */
	reviewModel?: string | null,
	/**  Default effort for in-app code reviews. Reserved. */
	reviewEffort?: string | null,
	/**  Start new sessions in fast mode. Reserved — not a `claude` spawn flag yet. */
	defaultFastMode?: boolean,
};

/**
 *  One way to install the hyprlayer CLI: the command to run and whether its
 *  package manager is present.
 */
export type CliInstallMethod = {
	id: CliInstallMethodId,
	/**  Package manager name, e.g. "Homebrew". */
	label: string,
	/**  Install command, run through the login shell. */
	command: string,
	available: boolean,
};

/**  A package manager that can install the hyprlayer CLI. */
export type CliInstallMethodId = "homebrew" | "winget" | "scoop";

/**  Who `codex` is currently authenticated as. */
export type CodexAuthStatus = {
	/**  `"chatgpt"`, `"apiKey"`, `"amazonBedrock"`, … or `None` when signed out. */
	method: string | null,
	/**  The signed-in ChatGPT account's email, when Codex reports one. */
	email: string | null,
	/**  The ChatGPT plan (`plus`, `pro`, `team`, …), when reported. */
	plan: string | null,
};

/**  One model Codex offers, as the composer's picker needs it. */
export type CodexModel = {
	/**  The id passed back as `turn/start`'s `model`. */
	id: string,
	displayName: string,
	/**  Reasoning-effort values this model accepts, in Codex's own order. */
	supportedEfforts: string[],
};

/**  Everything the Codex settings tab needs, read in ONE app-server session. */
export type CodexProbe = {
	auth: CodexAuthStatus,
	/**
	 *  Empty when Codex is signed out — it answers `model/list` with no rows
	 *  rather than failing. A probe that could not run at all is an `Err`, so
	 *  the two cases stay distinguishable.
	 */
	models: CodexModel[],
};

/**
 *  Codex harness defaults (Settings → Harnesses → Codex). Auth is NOT stored
 *  here — `codex login` owns it in `~/.codex`, and the app only reads the status.
 */
export type CodexSettings = {
	/**
	 *  Default model id for new Codex sessions (e.g. `"gpt-5.4-codex"`), as
	 *  returned by `model/list`. `None` keeps Codex's own configured default.
	 */
	defaultModel?: string | null,
	/**
	 *  Default reasoning effort for new sessions (`minimal`..`xhigh`). `None`
	 *  keeps the model's own default effort.
	 */
	defaultEffort?: string | null,
	/**
	 *  Model for the Commit/Ship/Revise action agents when the default harness is
	 *  Codex — these stages are mechanical git/PR plumbing, so a cheaper model
	 *  than the chat default is usually right. `None` ⇒ falls back to
	 *  `default_model`, then the first selected model.
	 */
	commitModel?: string | null,
	/**  Reasoning effort for the Commit/Ship/Revise action agents (Codex). */
	commitEffort?: string | null,
	/**
	 *  The model ids the user picked to expose in the composer's model picker.
	 *  Empty = none chosen yet (the Codex tab prompts the user to add some).
	 */
	selectedModels?: string[],
	/**
	 *  Personality/style for new Codex chats. Reserved — `thread/start` takes a
	 *  `personality`, but nothing sets it yet.
	 */
	personality?: string | null,
};

/**
 *  The hyprlayer CLI config file changed on disk (the CLI rewrote it, or the
 *  user edited it). Frontend should refetch bootstrap/project queries.
 */
export type ConfigChanged = null;

export type ConfigSummary = 
/**  No config file: first-run — onboarding should offer bootstrap. */
{ state: "missing"; path: string } | 
/**  Config exists but can't be used (parse error, future schema, ...). */
{ state: "error"; path: string; code: string; message: string; remedy: string | null } | { state: "ready"; path: string; user: string; backendKind: string; configured: boolean };

export type CreateDocInput = {
	/**  Repo path of the project the doc belongs to (None for global scope). */
	projectRepoPath: string | null,
	scope: string,
	docType: string,
	title: string,
	/**  Today's date from the user's locale, YYYY-MM-DD. */
	date: string,
	ticket: string | null,
	tags?: string[],
};

/**  One user-defined prompt in the library. */
export type CustomPrompt = {
	/**  Stable id (uuid) — referenced by the palette, chips, and shortcuts. */
	id?: string,
	name?: string,
	/**  The global body. */
	body?: string,
	/**  Per-project body overrides, keyed by project path. */
	overrides?: { [key in string]: string },
	/**
	 *  Keyboard chord in the frontend's canonical form (e.g. `"mod+shift+t"`);
	 *  `None` = unbound. Dispatched by the frontend, stored here so it rides
	 *  with the prompt.
	 */
	chord?: string | null,
	/**  Pinned prompts render as one-click chips above the session composer. */
	pinned?: boolean,
};

/**
 *  One immediate child of a directory in the "All Files" tree. `path` is
 *  relative to the worktree root (forward-slashed), suitable for the read/diff
 *  commands.
 */
export type DirEntry = {
	name: string,
	path: string,
	isDir: boolean,
};

export type DocContent = {
	meta: DocMeta,
	content: string,
	mtimeMs: number | null,
};

/**  Everything the UI needs to list and filter a document, sans body. */
export type DocMeta = {
	/**  Absolute path string — the canonical unique id. */
	id: string,
	/**  Path relative to its root, `/`-separated on every platform. */
	relPath: string,
	/**  Mapped repo name when the doc lives under `<repos_dir>/<name>/…`. */
	project: string | null,
	area: Area,
	/**
	 *  `"user" | "shared" | "global"` derived from the path; for
	 *  [`Area::Other`] falls back to `fm.scope` or `"shared"`.
	 */
	scope: string,
	/**  Profile that owns the root, `None` for the default backend. */
	profile: string | null,
	/**  `"git" | "obsidian"`. */
	backend: string,
	fm: Frontmatter,
	fmWarnings: string[],
	mtimeMs: number | null,
	sizeBytes: number | null,
};

/**  What sort of app an entry is, so the menu can group/label sensibly. */
export type EditorKind = 
/**  The OS file manager (Finder / Explorer / default handler). */
"files" | "editor" | "terminal";

/**
 *  One installed app the user can open a directory in. `openWith` is the value
 *  the frontend passes to `openPath(dir, openWith)`; `None` means "open with
 *  the OS default handler for a directory" (the file manager). `iconDataUrl` is
 *  a `data:image/png` of the app's real icon when we could rasterize one.
 */
export type EditorTarget = {
	id: string,
	name: string,
	kind: EditorKind,
	openWith: string | null,
	iconDataUrl: string | null,
};

/**  One CLI engine the multiplexer can launch in a PTY. */
export type Engine = {
	/**
	 *  Stable id: `"claude-code" | "codex" | "gemini"` for built-ins, a uuid for
	 *  custom engines.
	 */
	id?: string,
	/**  Display name, e.g. "Claude Code". */
	label?: string,
	/**  Single-glyph mark shown on the tab + in the menu (e.g. "✻", "◆", "✦"). */
	glyph?: string,
	/**
	 *  Theme custom-property *name* for the engine accent (e.g. `"--color-accent"`).
	 *  Never a raw hex — the frontend applies it as `var(<token>)` so it stays
	 *  theme-aware.
	 */
	accentToken?: string,
	/**  Executable to run, resolved on the user's login PATH (e.g. `"claude"`). */
	command?: string,
	/**  Extra arguments appended to the command. */
	args?: string[],
	/**  Whether this engine appears in the `+` menu. */
	enabled?: boolean,
	/**  True for the three seeded engines; false for user-added customs. */
	builtin?: boolean,
};

/**  How a claude process ended. */
export type ExitOutcome = 
/**  Emitted a terminal `result` then exited 0. */
"completed" | 
/**  Stopped after an app-initiated interrupt. */
"interrupted" | 
/**  Exited without a terminal `result` (or non-zero) — treated as a crash. */
"crashed" | 
/**  We killed the process tree (hard stop / cleanup). */
"killed" | 
/**
 *  The app took the process down as part of its own lifecycle — quitting, or
 *  relaunching this session under new settings — not something that happened
 *  to the session. Terminal for the live process only: nothing is persisted,
 *  so the session replays clean and resumable (see the forwarder's `Exited`
 *  arm).
 */
"detached" | 
/**  Failed to spawn / disappeared immediately. */
"spawn_failed";

/**
 *  The two texts a CodeMirror merge view diffs. The frontend computes the diff,
 *  so we hand it whole-file contents rather than a patch. The `*_exists` flags
 *  distinguish an empty file from an absent one (added/deleted), which the
 *  viewer uses to force unified mode.
 */
export type FileSides = {
	original: string,
	modified: string,
	originalExists: boolean,
	modifiedExists: boolean,
};

export type FmPatchDto = {
	set?: FmSetEntry[],
	remove?: string[],
};

export type FmSetEntry = {
	key: string,
	value: FmValueDto,
};

export type FmValueDto = { kind: "str"; value: string } | { kind: "list"; values: string[] } | { kind: "null" };

/**
 *  The 10-field thought schema (hyprlayer-cli/src/backends/schema.rs), all
 *  optional because the parser must tolerate anything.
 */
export type Frontmatter = {
	title?: string | null,
	type?: string | null,
	date?: string | null,
	status?: string | null,
	ticket?: string | null,
	project?: string | null,
	scope?: string | null,
	tags?: string[],
	author?: string | null,
	related?: string[],
	/**
	 *  Unknown keys, preserved for display and round-tripping.
	 *  Unknown keys in display form: strings as-is, everything else compact
	 *  JSON, null as "". Read-only context for the UI — the line-surgical
	 *  patcher preserves the underlying bytes regardless. (Stringified
	 *  because specta forbids serde_json::Value's i64 arm in IPC types.)
	 */
	extra?: { [key in string]: string },
};

/**  Whether this process can read files macOS gates behind Full Disk Access. */
export type FullDiskAccess = "granted" | 
/**
 *  The probe returned EPERM. Either the grant was never added, or it was
 *  recorded against a code signature this build no longer matches — in
 *  which case System Settings still shows the toggle on while every gated
 *  read fails.
 */
"denied" | 
/**  Not a macOS gate, or the probe file is missing. Never nag on this. */
"unknown";

/**
 *  One changed file within a worktree, as it appears in the staged or unstaged
 *  list. `change` is one of: added | modified | deleted | renamed | untracked |
 *  typechange | conflict.
 */
export type GitFileEntry = {
	path: string,
	change: string,
};

/**  User-tunable git behaviour. Surfaced in Settings → Git. */
export type GitSettings = {
	/**
	 *  Branch-name prefix for new worktrees. `None` keeps the built-in
	 *  `hyprlayer/` default; a value (e.g. `"feature/"`) is used verbatim.
	 */
	branchPrefix?: string | null,
	/**
	 *  Delete the local branch when archiving a workspace. Default `true`,
	 *  matching the historical behaviour.
	 */
	deleteBranchOnArchive?: boolean,
	/**  Auto-archive a workspace once its PR is observed merged. */
	archiveOnMerge?: boolean,
	/**
	 *  Queue a GitHub auto-merge (`gh pr merge --auto`) so the PR lands once
	 *  required checks pass. Requires auto-merge enabled on the repo.
	 */
	automerge?: boolean,
	/**
	 *  Strip git-ignored files (build output, deps) from a worktree before
	 *  archiving so archives don't balloon. Files matched by the repo's
	 *  `worktree.copy` patterns are preserved. Default `true`.
	 */
	pruneIgnoredOnArchive?: boolean,
};

/**  One of the user's GitHub repos, for the clone dialog's "Recent repos" list. */
export type GithubRepo = {
	nameWithOwner: string,
	description?: string | null,
	url: string,
	/**  Last push, ISO-8601 as GitHub returns it. None on repos with no commits. */
	pushedAt: string | null,
	private: boolean,
};

/**
 *  Which harness backs a session — the vocabulary the store persists
 *  (`sessions.harness`), the IPC surface selects on, and the shell dispatches
 *  drivers by. sqlite stores `as_str` TEXT; read back via the tolerant
 *  [`Harness::parse`].
 */
export type Harness = "claude" | "opencode" | "codex";

export type HealthCheck = {
	id: string,
	label: string,
	status: CheckStatus,
	detail: string | null,
	remedy: string | null,
};

export type HealthReport = {
	checks: HealthCheck[],
};

/**
 *  User overrides for keyboard shortcuts. Surfaced in Settings → Keyboard.
 * 
 *  Only *overrides* live here — the per-OS defaults are owned by the frontend
 *  catalog so they can change without a settings migration. Keys are stable
 *  command ids (e.g. "nav.dashboard"); a `Some(chord)` is a custom binding,
 *  `None` means the command is explicitly unbound, and an absent key means
 *  "use the catalog default".
 */
export type KeybindingSettings = {
	overrides?: { [key in string]: string | null },
};

export type LinkStatus = 
/**  Links exist and resolve. */
"ok" | 
/**  Backend has no filesystem tree (notion/anytype) — nothing to link. */
"unsupported" | 
/**  Links missing or broken. */
"broken";

/**  How the Merge button merges — picked per-PR by the user. */
export type MergeMethod = "squash" | "merge" | "rebase";

/**
 *  GitHub's mergeability verdict for the PR, from `gh`'s `mergeable` field.
 *  Distinguishes a clean merge from a conflicting branch — which we surface as a
 *  row in the checks panel — and from GitHub's transient `UNKNOWN` (still being
 *  computed server-side).
 */
export type MergeableState = 
/**  No conflicts — the PR can merge cleanly. */
"mergeable" | 
/**  The branch conflicts with its base and must be resolved before merging. */
"conflicting" | 
/**  GitHub hasn't finished computing mergeability yet (transient). */
"unknown";

/**  One model's authoritative context window, from `GET /v1/models`. */
export type ModelWindow = {
	/**
	 *  Canonical model id, e.g. `"claude-fable-5"` (`data[].id`). Bare — the API
	 *  exposes no `[1m]` variants, so the UI strips that suffix before lookup.
	 */
	id: string,
	/**  Context window in tokens (`max_input_tokens`) — the meter's denominator. */
	contextWindow: number,
};

/**
 *  Multiplexer mode (Settings → Advanced). When enabled, a new agent tab
 *  launches a real CLI in a persistent PTY instead of the native chat, and the
 *  `+` on the agent tab strip lets the user pick which engine. The frontend is
 *  the only consumer — the backend just stores the config and (separately)
 *  spawns the chosen command via `agent_open`.
 */
export type MultiplexerSettings = {
	/**
	 *  Master switch. `false` (default) keeps every agent tab the native chat;
	 *  nothing about the shell changes until this is on.
	 */
	enabled?: boolean,
	/**
	 *  Engine a new tab launches with (also bound to ⌘T). Defaults to
	 *  `"claude-code"`. If it names a disabled/removed engine the frontend falls
	 *  back to the first enabled one.
	 */
	defaultEngineId?: string,
	/**  Badge the tab + fire a system notification when an agent is blocked. */
	notifyOnBlocked?: boolean,
	/**
	 *  Reattach running PTYs when the app relaunches. A child process can't
	 *  outlive the app it was spawned from, so in practice this relaunches the
	 *  engine on next launch rather than resurrecting a dead process.
	 */
	persistAcrossRestarts?: boolean,
	/**
	 *  The engines offered in the `+` menu. Seeded with the three built-ins;
	 *  users can disable any or add custom commands ("Add CLI…").
	 */
	engines?: Engine[],
};

/**
 *  Controls native OS notifications fired when a session moves into the
 *  needs-you state (awaiting permission/question) while the window is
 *  unfocused. The frontend reads this on every transition; toggling the
 *  setting takes effect on the next event without a restart.
 */
export type NotificationSettings = {
	/**
	 *  Master switch. `true` (default) fires a toast when an agent needs you;
	 *  `false` suppresses all notifications regardless of `sound`.
	 */
	enabled?: boolean,
	/**  Whether the toast plays the OS default notification sound. */
	sound?: boolean,
};

/**  One model installed on the Ollama server, from `GET /api/tags`. */
export type OllamaModelInfo = {
	/**
	 *  The canonical id, e.g. `"qwen2.5-coder:7b"` (the `models[].name` field).
	 *  Used verbatim as the `models` key in the `provider.ollama` block and, with
	 *  an `ollama/` prefix, as the composer model id.
	 */
	id: string,
	/**  Architecture family (e.g. `"qwen2"`), for display. */
	family: string | null,
	/**  Human parameter size (e.g. `"7.6B"`), for display. */
	parameterSize: string | null,
};

/**
 *  Ollama harness defaults (Settings → Harnesses → Ollama). Local models are run
 *  *through* the OpenCode harness: selecting one sets `harness=opencode` with an
 *  `"ollama/<model>"` model id. The provider definition (base URL + model list)
 *  is mirrored into OpenCode's `opencode.json` as a `provider.ollama` block —
 *  see `hyprlayer_core::opencode::config::set_ollama_provider`.
 */
export type OllamaSettings = {
	/**
	 *  Base URL of the Ollama server. `None`/empty ⇒ [`DEFAULT_OLLAMA_ENDPOINT`].
	 *  May be a remote host; a local install is not required.
	 */
	endpoint?: string | null,
	/**
	 *  Bare Ollama model ids the user chose to expose (e.g. `"qwen2.5-coder:7b"`).
	 *  Each surfaces as an `"ollama/<id>"` row in the composer's model picker.
	 */
	selectedModels?: string[],
	/**
	 *  Default local model for new sessions, as an `"ollama/<id>"` id. `None`
	 *  keeps no Ollama default.
	 */
	defaultModel?: string | null,
	/**
	 *  `"ollama/<id>"` model for the Commit/Ship/Revise action agents when Ollama
	 *  is the default harness. `None` ⇒ falls back to `default_model`, then the
	 *  first selected model. Runs through OpenCode like every Ollama session.
	 */
	commitModel?: string | null,
};

/**  Reachability + installed-model snapshot for the configured Ollama endpoint. */
export type OllamaStatus = {
	/**
	 *  `true` when `GET <endpoint>/api/tags` answered. This is the authoritative
	 *  "Ollama is usable" signal for both local and remote setups.
	 */
	reachable: boolean,
	/**  The effective base URL probed (default or user-configured). */
	endpoint: string,
	/**  Models installed on the server, sorted by id. Empty when unreachable. */
	models: OllamaModelInfo[],
};

/**
 *  OpenCode harness defaults (Settings → Harnesses → OpenCode). Provider API
 *  keys themselves are NOT stored here — they live in OpenCode's own
 *  `auth.json` so the `opencode` CLI uses them natively (see `opencode::config`).
 */
export type OpenCodeSettings = {
	/**
	 *  Default model for new OpenCode sessions, as a `"provider/model"` id
	 *  (e.g. `"anthropic/claude-sonnet-4-5"`). Mirrored into `opencode.json`'s
	 *  `model` field so the CLI agrees. `None` keeps OpenCode's own default.
	 */
	defaultModel?: string | null,
	/**
	 *  `"provider/model"` id for the Commit/Ship/Revise action agents when the
	 *  default harness is OpenCode. `None` ⇒ falls back to `default_model` (or
	 *  the harness's own default). May be an `"ollama/<id>"` id.
	 */
	commitModel?: string | null,
	/**
	 *  The `"provider/model"` ids the user picked to expose in the composer's
	 *  model picker when the OpenCode harness is selected. Empty = none chosen
	 *  yet (the OpenCode tab prompts the user to add some).
	 */
	selectedModels?: string[],
};

/**
 *  One configured provider credential, as surfaced to the UI. The raw key is
 *  deliberately never returned — only that a credential exists and its kind.
 */
export type OpencodeAuthEntry = {
	/**  models.dev provider id (e.g. `"anthropic"`, `"openai"`). */
	provider: string,
	/**  The stored credential `type`: `"api"`, `"oauth"`, `"wellknown"`, … */
	kind: string,
};

export type OpencodeCatalog = {
	providers: CatalogProvider[],
	/**  `"network"` | `"cache"` | `"bundled"` — lets the UI show an offline hint. */
	source: string,
};

/**
 *  Per-stage permission posture (maps to claude's `--permission-mode`). Also
 *  the wire type for a user-chosen override (serialized as the CLI's own
 *  camelCase flag strings, which the frontend already speaks).
 */
export type PermissionMode = "default" | "acceptEdits" | "plan" | "bypassPermissions";

/**  One CI check on the PR's head commit, for the per-check breakdown popover. */
export type PrCheck = {
	name: string,
	/**  Per-check outcome — only `Pending`/`Passing`/`Failing` (never `None`). */
	state: ChecksState,
	/**  Link to the check's run/details page, when GitHub provides one. */
	url: string | null,
};

/**  Open/merged/closed — the PR's lifecycle state from `gh`'s `state` field. */
export type PrState = "open" | "merged" | "closed";

/**  A branch's pull request as the PR status bar renders it. */
export type PrStatus = {
	number: number,
	url: string,
	title: string,
	state: PrState,
	/**
	 *  GitHub reports the PR cleanly mergeable (no conflicts). True only for
	 *  `MERGEABLE`; the Merge button gates on this.
	 */
	mergeable: boolean,
	/**
	 *  GitHub's full mergeability verdict. Carries the `CONFLICTING` distinction
	 *  `mergeable` discards, so the checks panel can show a merge-conflict row.
	 */
	mergeableState: MergeableState,
	checks: ChecksState,
	checksTotal: number,
	checksPassed: number,
	checksFailed: number,
	/**  The individual checks, for the "which ran?" breakdown popover. */
	checksList: PrCheck[],
	/**
	 *  GitHub's review verdict, or `None` when the PR requires no review / has no
	 *  decision yet. The Merge button blocks while this is `ReviewRequired` or
	 *  `ChangesRequested`.
	 */
	reviewDecision: ReviewDecision | null,
};

/**
 *  A workstream's PR status changed server-side — it merged, its checks
 *  settled, or a PR appeared/disappeared for the branch. The backend PR watcher
 *  (`crate::pr_watch`) diffs each poll and emits this only on a real change; the
 *  frontend refetches that workstream's PR query so the merge/archive bar stays
 *  in sync without the UI polling `gh` on a timer.
 */
export type PrStatusChanged = {
	workstreamId: string,
};

/**
 *  A lightweight open-PR row for the "Attach PR" picker: enough to display a
 *  choice and attach it by number. From `gh pr list --json …`.
 */
export type PrSummary = {
	number: number,
	title: string,
	/**
	 *  The PR's source branch, shown as a subtitle so two PRs with similar
	 *  titles are still distinguishable.
	 */
	headRefName: string,
	url: string,
	isDraft: boolean,
};

export type Project = {
	/**  Absolute path of the app-owned clone (`~/hyprlayer/repos/<name>`). */
	path: string,
	/**  Human-facing project name (the app registry name, e.g. `brightblock.ai`). */
	mappedName: string,
	/**
	 *  The thoughts `repoMappings` key this repo resolves to — what docs are
	 *  indexed and worktrees created under. CLI-sanitized, so it can differ from
	 *  `mapped_name` (`brightblock.ai` → `brightblock_ai`). Filter docs by THIS.
	 */
	thoughtsProject: string,
	profile: string | null,
	backendKind: string,
	existsOnDisk: boolean,
	/**  The git source this clone tracks; None for a local-only repo. */
	originUrl: string | null,
	/**  How it was added. `folder` has no git and no thoughts mapping. */
	source: ProjectSource,
};

export type ProjectDetail = {
	project: Project,
	/**
	 *  None for `folder` projects — they have no thoughts mapping, so the
	 *  `hyprlayer storage info` subprocess is never run for them.
	 */
	storage: StorageInfo | null,
	thoughtsRoot: string | null,
};

/**
 *  How a project entered the registry. `Folder` is the odd one out: a plain
 *  directory with no git and no thoughts mapping, so every git, PR, and
 *  hyprlayer-CLI surface is skipped for it.
 * 
 *  Tolerance: an unrecognized stored value reads as `Disk` — the in-place,
 *  touch-nothing kind — so a mangled row can never make removal delete files
 *  the app doesn't own.
 */
export type ProjectSource = 
/**  Cloned from a URL into the repos root. */
"clone" | 
/**  An existing git repo imported in place. */
"disk" | 
/**  A local directory that isn't a git repo. */
"folder";

/**
 *  The live values behind prompt `{{variables}}` for a workstream. The frontend
 *  fetches this at run time to substitute a custom prompt's body before sending
 *  it (built-in Commit/Ship bodies are substituted backend-side at launch).
 */
export type PromptContext = {
	branch: string,
	/**  The PR target branch, `origin/`-stripped. */
	baseBranch: string,
	/**  Working-tree change summary, e.g. `"4 files (+182 −40)"`. */
	changedFiles: string,
	/**  Working-tree diff vs HEAD, truncated backend-side. */
	diff: string,
	/**  Most recent commit subject. */
	lastCommit: string,
};

/**
 *  The stock bodies of the built-in prompts — what Settings → Prompts shows,
 *  edits against, and resets to. Owned by `hyprlayer_core::pipeline` (the
 *  composer), surfaced here so the frontend never mirrors the literals.
 */
export type PromptDefaults = {
	commit: string,
	/**  A template — `{{base_branch}}` resolves at send time. */
	ship: string,
};

/**
 *  The prompt library (Settings → Prompts).
 * 
 *  Built-in prompts (Commit, Ship) are global; `builtin_bodies` holds a body
 *  override keyed by prompt id (`"commit"` | `"ship"`), and an absent key means
 *  the stock text (owned by `hyprlayer_core::pipeline`). Custom prompts are
 *  user-defined and may carry per-project body overrides. Bodies may contain
 *  `{{variable}}` tokens resolved from the worktree at send time.
 */
export type PromptSettings = {
	builtinBodies?: { [key in string]: string },
	custom?: CustomPrompt[],
};

/**
 *  Defaults for each agent provider/harness. Claude, OpenCode and Codex are all
 *  real harnesses; Ollama runs local models *through* the OpenCode harness.
 */
export type ProviderSettings = {
	/**
	 *  The harness new sessions default to, and the one the Commit/Ship actions
	 *  run on: `"claude"`, `"opencode"` or `"codex"` (Ollama runs *through*
	 *  OpenCode). `None`/absent ⇒ `"claude"`. Read by the composer and the
	 *  commit/ship launch path; the picker still overrides it per tab.
	 */
	defaultHarness?: string | null,
	/**  Anthropic Claude (the `claude` CLI). */
	claude?: ClaudeSettings,
	/**  OpenCode (the `opencode` CLI) — multi-provider harness. */
	opencode?: OpenCodeSettings,
	/**  Ollama — local/remote model server, surfaced through the OpenCode harness. */
	ollama?: OllamaSettings,
	/**  OpenAI Codex (the `codex` CLI, driven via its app-server). */
	codex?: CodexSettings,
};

/**
 *  What [`pull_base`] did — surfaced to the GIT panel so it can report the
 *  result inline (a clean merge vs. conflicts the user must resolve by hand).
 */
export type PullOutcome = 
/**  The branch already contains the base's commits — nothing to pull. */
{ kind: "upToDate" } | 
/**  The base merged cleanly (fast-forward or a new merge commit). */
{ kind: "merged" } | 
/**
 *  The merge stopped on conflicts. The worktree is left mid-merge (NOT
 *  aborted) so the listed files show up conflicted in the Changes panel; the
 *  user resolves them and commits (or runs `git merge --abort`).
 */
{ kind: "conflicts"; files: string[] };

export type QueryResult = {
	/**  Matches before limit/offset. */
	total: number,
	items: DocMeta[],
};

/**
 *  A quit was requested (⌘Q or the window's close button) while "Confirm before
 *  quitting" is on. The backend has already cancelled the close by the time this
 *  lands — the frontend raises the confirm dialog, and nothing exits unless the
 *  user confirms (`quit_app`).
 */
export type QuitRequested = null;

/**
 *  Quit confirmation (Settings → General). Quitting takes every running agent,
 *  PTY, and lifecycle script down with it, so ⌘Q and the window's close button
 *  ask first. The dialog's "Don't ask again" clears `confirm`; the Settings
 *  toggle puts it back.
 */
export type QuitSettings = {
	/**  `true` (default) prompts before quitting; `false` exits immediately. */
	confirm?: boolean,
};

/**
 *  How a browsed disk path looks as a candidate project, for the Add-project
 *  disk flow.
 */
export type RepoPathStatus = 
/**  The path doesn't exist or isn't a directory. */
"missing" | 
/**  Exists, but isn't a git repo — offer to `git init` it. */
"nonGit" | 
/**  A bare repository — no working tree to cut a worktree from. */
"bare" | 
/**  A git repo whose HEAD is unborn (no commits yet). */
"unborn" | 
/**  A ready git repo (working tree with at least one commit). */
"ready";

/**
 *  GitHub's aggregate review verdict for the PR, from `gh`'s `reviewDecision`
 *  field. The `Option` on [`PrStatus`] is `None` when the PR requires no review —
 *  then there's nothing to gate on.
 */
export type ReviewDecision = 
/**  A required review is satisfied — approved with no changes outstanding. */
"approved" | 
/**  A reviewer requested changes; the author must address them before merging. */
"changesRequested" | 
/**  A required review is still outstanding — the PR is waiting on a reviewer. */
"reviewRequired";

/**
 *  Rewind a session to the N-th (1-based) user turn, discarding that turn and
 *  everything after it. Two paths:
 * 
 *  * **Live rewind (preferred).** If the session is live and its harness supports
 *    it, we ask the harness to truncate the model's in-memory conversation to this
 *    turn — claude's `rewind_conversation` control request
 *    (see [`ClaudeDriver::rewind_to_ordinal`]), Codex's `thread/rollback` — then
 *    keep that SAME process alive and hand its event stream to the caller's new
 *    channel (see [`live_rewind_handoff`]). The model genuinely forgets the dropped
 *    turns. We must NOT kill + resume here: claude's peel does not truncate its
 *    on-disk transcript, so a resume would reload the un-rewound history.
 *  * **Log-only fallback.** If the model rewind isn't available (session not live,
 *    OpenCode, a turn from before the current generation, the first turn, or a
 *    harness refusal) we kill + cut + resume: the UI/log truncate but the model
 *    keeps its memory. `permission_mode` re-applies the session's posture on this
 *    re-spawn (as [`resume_session`]/[`restart_session`] do) — `None` would drop a
 *    bypass session back to the stage default and start prompting again.
 * 
 *  `user_turn` is the 1-based ordinal of the clicked user bubble (the N-th
 *  `userMessage` event). Returns the existing [`Session`] plus which path ran, so
 *  the caller can tell a TRUE rewind (the model forgot) from a log-only prune (it
 *  still recalls the dropped turns) instead of assuming success.
 */
export type RewindResult = {
	session: Session,
	/**
	 *  True when the harness's own conversation was truncated on the live process
	 *  (the model genuinely forgot the dropped turns); false when we could only
	 *  prune the app log (not live / OpenCode / a pre-generation or first turn / a
	 *  harness refusal) — the model still recalls them.
	 */
	liveRewound: boolean,
};

/**  Outcome of a script run, shown as a status pill. */
export type RunPhase = "running" | "passed" | "failed";

/**
 *  One field of the 10-field thought metadata schema
 *  (`hyprlayer-cli/src/backends/schema.rs`).
 */
export type SchemaFieldInfo = {
	name: string,
	kind: string,
	options?: string[] | null,
	required: boolean,
};

/**
 *  Which lifecycle script. Persisted as the `[scripts]` keys and carried on the
 *  `ScriptRunChanged` event so the UI can route a run to the right tab/pill.
 */
export type ScriptKind = "setup" | "run" | "archive";

/**
 *  A lifecycle script (Setup/Run/Archive) changed state for a workstream: it
 *  started running, detected its dev-server port, or finished. Drives the dock
 *  script tabs + status pills and the left rail's green "Run alive" indicator.
 *  The fine-grained output streams over the per-run Channel (like terminals),
 *  not this event.
 */
export type ScriptRunChanged = {
	workstreamId: string,
	kind: ScriptKind,
	phase: RunPhase,
	exitCode: number | null,
	/**  Set when a Run's dev-server port is detected (phase stays `running`). */
	port: number | null,
};

/**
 *  Snapshot of a workstream's script runtime, for UI hydration on (re)mount —
 *  the dock/rail read this to recover the live Run + last-run pills after a
 *  remount or workstream switch.
 */
export type ScriptRuntime = {
	/**  terminal_id of the live Run PTY, if one is running (else `null`). */
	runTerminalId: string | null,
	/**  Detected dev-server port for the live Run, if any. */
	port: number | null,
	/**  Last-run status per script that has run this session. */
	statuses: ScriptStatus[],
};

/**
 *  Per-project lifecycle scripts, inherited by every workstream. Each value is a
 *  free-form multi-line block of shell commands run in the workstream's worktree
 *  root; an empty string means "unconfigured". Run sequentially — a non-zero
 *  exit halts the block (see `crate::scripts::build_block`).
 */
export type ScriptSettings = {
	/**  Runs once when a new worktree is created. */
	setup?: string,
	/**  Runs each time the user presses Run; the prior Run process is stopped first. */
	run?: string,
	/**  Runs before a workstream is archived. */
	archive?: string,
};

/**  Last-run status for one script in one workstream. `at` is unix-millis. */
export type ScriptStatus = {
	kind: ScriptKind,
	phase: RunPhase,
	exitCode: number | null,
	at: number | null,
};

export type SeedError = {
	entry: string,
	message: string,
};

export type SeedReport = {
	/**  Repo-relative paths actually written into the worktree. */
	copied: string[],
	/**  Entries (literal or glob) that matched nothing in the repo. */
	missing: string[],
	/**  Per-entry errors that didn't prevent other entries from copying. */
	errors: SeedError[],
};

export type Session = {
	id: string,
	workstreamId: string,
	stage: Stage,
	/**  Which harness backs the session. */
	harness: Harness,
	/**
	 *  The harness's own session id (set on init; drives resume). claude's
	 *  session id for Claude Code, the opencode session id for OpenCode, the
	 *  thread id for Codex.
	 */
	claudeSessionId: string | null,
	cwd: string,
	state: SessionState,
	model: string | null,
	/**  Cumulative cost reported by the latest `result` event. */
	costUsd: number | null,
	startedAt: number | null,
	endedAt: number | null,
	exitSummary: string | null,
};

/**
 *  One event in a session's lifetime. Ordered; the sequence per session is
 *  monotonic. Serialized tagged so the frontend can switch on `kind`. Tool
 *  inputs are carried as compact JSON strings (not `serde_json::Value`) so the
 *  type exports cleanly through specta; the UI parses them for display.
 */
export type SessionEvent = 
/**  Session is up; claude assigned its own id (used for `--resume`). */
{ kind: "init"; claudeSessionId: string; model: string | null } | 
/**
 *  A user turn the app sent to claude. claude never echoes the human prompt
 *  on stdout (it's input), so the driver emits this itself purely so the turn
 *  is persisted and replays after a restart. It is NOT forwarded to the live
 *  UI (which already shows the message optimistically) — persist-only, so the
 *  live transcript isn't double-stamped. `stage` is the stage label for the
 *  session's opening prompt, else null (a follow-up).
 */
{ kind: "userMessage"; text: string; stage: string | null; 
/**
 *  Name of the custom prompt this turn ran, else null for a typed turn.
 *  `text` stays the exact body the agent received (vars substituted), so
 *  the UI can collapse it into a card titled with this name and expand it
 *  back to what was actually sent. Defaulted: rows persisted before this
 *  field existed still deserialize.
 */
promptName?: string | null } | 
/**
 *  Streaming text delta (live typing). Coalesced into `AssistantText` on
 *  turn completion — the UI shows partials, then replaces with the final.
 */
{ kind: "partialText"; text: string; parentId: string | null } | 
/**  A completed assistant text block. */
{ kind: "assistantText"; text: string; parentId: string | null } | 
/**  A completed thinking block (shown collapsed). */
{ kind: "thinking"; text: string; parentId: string | null } | 
/**
 *  The agent invoked a tool. `input` is compact JSON. `parent_id` is the
 *  `Task` tool-use id when this runs inside a subagent (else null).
 */
{ kind: "toolUse"; id: string; name: string; input: string; parentId: string | null } | 
/**  Result of a tool the agent ran. */
{ kind: "toolResult"; toolUseId: string; content: string; isError: boolean; parentId: string | null } | 
/**
 *  Permission prompt — the UI renders an Allow/Deny card; reply via the
 *  driver's `respond_permission` with this `request_id`. `input` is compact
 *  JSON of the tool's arguments.
 */
{ kind: "permissionAsk"; requestId: string; toolName: string; input: string } | 
/**
 *  The agent invoked `AskUserQuestion` — rather than a yes/no permission
 *  gate, the UI renders the questions interactively above the composer and
 *  the user picks answers; reply via the driver's `answer_question` with this
 *  `request_id`. `questions` is compact JSON of the `questions` array (each:
 *  `question`/`header`/`multiSelect`/`options[]{label,description}`).
 */
{ kind: "questionAsk"; requestId: string; questions: string } | 
/**
 *  A live context-window reading (input tokens in context), emitted per
 *  assistant message so the meter updates DURING a multi-tool turn — not
 *  only at `TurnDone`. Persisted (it's tiny) so the meter survives a restart
 *  even when a turn was interrupted before its `TurnDone` ever landed.
 */
{ kind: "usage"; contextTokens: number } | 
/**
 *  The model's context window in tokens — the meter's DENOMINATOR (`Usage` is
 *  the numerator). Emitted once at session start when the backend knows the
 *  value authoritatively: an Ollama model is launched with a fixed `num_ctx`
 *  the UI can't infer from the `provider/model` id. Absent for models we
 *  don't pin (Claude, hosted OpenCode providers) — the UI then falls back to
 *  its own per-model table. Persisted so it survives a restart/replay.
 */
{ kind: "contextWindow"; tokens: number } | 
/**
 *  A turn finished; carries cumulative cost so far and the context-window
 *  fill (input tokens in context for the turn) for the UI's context meter.
 */
{ kind: "turnDone"; costUsd: number | null; numTurns: number | null; contextTokens: number | null } | 
/**
 *  claude auto- or manually compacted the conversation. The transcript
 *  renders a divider so a silent compaction stretch is legible instead of
 *  looking like a stuck turn. `trigger` is "auto" or "manual"; `pre_tokens`
 *  is the context fill just before the compact, when reported.
 */
{ kind: "compactBoundary"; trigger: string; preTokens: number | null } | 
/**
 *  A command queued into a running session — a scheduled-wakeup prompt, a slash
 *  command queued behind a busy turn — started or finished. The transcript renders
 *  a seam on `started`, because claude never echoes the injected prompt to us: the
 *  turn simply begins, and without this marker it reads as the agent spontaneously
 *  resuming. `completed`/`cancelled` close the bracket and render nothing (the
 *  turn's own content already shows how it ended). Both carry the same
 *  `command_uuid`.
 */
{ kind: "commandLifecycle"; commandUuid: string; state: string } | 
/**
 *  A background shell task (spawned by `Bash{run_in_background:true}`) reached
 *  a terminal state. claude emits the underlying `task_notification`
 *  asynchronously the moment the shell finishes — even if the agent never
 *  polled it — so this is how the UI learns a fire-and-forget background task
 *  is done and drops it from the live "background tasks" indicator (the
 *  poll/stop paths miss the common case where the agent just moves on).
 *  `status` is "completed" or "failed"; `tool_use_id` is the spawning `Bash`
 *  call (the UI's direct transcript key), `task_id` the background shell id.
 */
{ kind: "backgroundTaskUpdate"; taskId: string; toolUseId: string | null; status: string } | 
/**
 *  A new `claude` process took over an existing session via `--resume`
 *  (permission/model change, app-restart resume, log-only rewind fallback).
 *  The forwarder emits it once at the start of a relaunch — distinct from
 *  claude's per-turn `init` — so the UI drops background tasks the now-dead
 *  prior process owned (their completion notification can never arrive).
 */
{ kind: "relaunched" } | 
/**
 *  A LIVE rewind truncated this session's conversation IN PLACE: the same
 *  `claude` process had its model memory peeled by `rewind_conversation` (see
 *  [`ClaudeDriver::rewind_to_ordinal`]). Emitted once, like [`Relaunched`], so
 *  the UI settles the transcript at the new boundary — but the process is
 *  UNCHANGED, so (unlike a relaunch) its still-running background tasks can
 *  still complete-notify and must NOT be dropped.
 */
{ kind: "rewound" } | 
/**  An unparseable / unknown stdout line — surfaced, never fatal. */
{ kind: "protocolError"; detail: string; raw: string } | 
/**  The process ended. Terminal: no further events for this session. */
{ kind: "exited"; outcome: ExitOutcome; code: number | null; stderrTail: string };

/**
 *  Coarse session state change, for board/sidebar badges (the fine-grained
 *  transcript flows over the per-session Channel, not this global event).
 */
export type SessionLifecycle = {
	sessionId: string,
	workstreamId: string,
	/**  Matches the `sessions.state` column. */
	state: SessionState,
};

/**
 *  A session's full lifecycle state — persisted in `sessions.state` and carried
 *  by the `session-lifecycle` event. The five terminal variants mirror
 *  [`ExitOutcome`]; `Idle` is a live-but-between-turns session. sqlite stores
 *  `as_str` TEXT; rows read back through the tolerant [`SessionState::parse`]
 *  (unknown ⇒ `Crashed`: terminal and conservative, so the UI never treats a
 *  state it doesn't understand as a live session to re-attach).
 */
export type SessionState = "idle" | "starting" | "running" | "awaiting_permission" | "awaiting_question" | "completed" | "interrupted" | "killed" | "spawn_failed" | "crashed";

/**  One slash command offered in the composer's `/` autocomplete. */
export type SlashCommand = {
	/**  What the user types after `/`, e.g. `research_codebase`. */
	name: string,
	/**  One-line summary from the file's frontmatter (or first prose line). */
	description: string,
	/**  `project` | `user` — which `.claude` root supplied it (for the label). */
	source: string,
};

export type SortKey = 
/**  Text-match score; without `text` this falls through to `Date`. */
"relevance" | "date" | "mtime" | "title";

/**
 *  The pipeline stages — the canonical wire enum for a workstream/session's
 *  pipeline position. sqlite still stores its `as_str` TEXT; rows read back
 *  through the tolerant [`Stage::parse`]. Wire deserialization is strict — the
 *  generated bindings union makes an unknown value a TS type error, and specta
 *  cannot render `#[serde(other)]` on string enums.
 */
export type Stage = "research" | "plan" | "implement" | "validate" | "commit" | "ship" | "revise" | "general";

/**
 *  Composer choices for a new session, bundled so the command stays within
 *  specta's argument-count limit.
 */
export type StartOpts = {
	/**  Which harness to run; `None` defaults to Claude. */
	harness?: Harness | null,
	/**  For Claude: a model key/flag. For OpenCode: a `"provider/model"` id. */
	model?: string | null,
	effort?: string | null,
	/**  `--permission-mode` override; `None` keeps the stage's default posture. */
	permissionMode?: PermissionMode | null,
	/**
	 *  Name of the custom prompt that opened this session, when one did. Rides
	 *  onto the persisted `UserMessage` so the transcript collapses the body
	 *  into a card on replay.
	 */
	promptName?: string | null,
};

/**
 *  A freshly-started session plus the composed first prompt (pre-docs), so the
 *  frontend can echo exactly what the agent received. The composition is
 *  user-configurable (Settings → Prompts overrides + `{{variable}}`
 *  substitution), so the frontend no longer mirrors it.
 */
export type StartedSession = {
	session: Session,
	/**
	 *  The composed first prompt WITHOUT the `Relevant documents:` suffix —
	 *  attached docs render as pin cards in the echo, not as raw paths.
	 */
	prompt: string,
};

/**  Payload of `hyprlayer storage info --json`. */
export type StorageInfo = {
	backend: string,
	settings?: StorageSettings,
	projectPath?: string,
	mappedName?: string | null,
	profile?: string | null,
	user?: string | null,
	schema?: SchemaFieldInfo[],
};

/**
 *  Backend settings from `storage info --json`. The CLI emits a different
 *  key set per backend kind; this is the union, all optional.
 */
export type StorageSettings = {
	thoughtsRepo?: string | null,
	reposDir?: string | null,
	globalDir?: string | null,
	vaultPath?: string | null,
	vaultSubpath?: string | null,
	contentRoot?: string | null,
	parentPageId?: string | null,
	databaseId?: string | null,
	spaceId?: string | null,
	typeId?: string | null,
	apiTokenEnv?: string | null,
};

/**  One persisted event, for replay into a freshly-attached UI Channel. */
export type StoredEvent = {
	/**  Monotonic per-session sequence (f64 for IPC; small integers in practice). */
	seq: number | null,
	kind: string,
	/**  The full `SessionEvent` JSON. */
	payload: string,
	createdAt: number | null,
};

export type SyncReport = {
	output: string,
};

/**
 *  Auto-generated agent-tab titles. When enabled, a new agent tab summarizes the
 *  user's first prompt into a short title via a small model. Surfaced in
 *  Settings → General. The model can be a Claude or Codex model, or — so
 *  opencode-only users are covered — one of their configured OpenCode models.
 */
export type TabTitleSettings = {
	/**
	 *  Master switch. `true` (default) titles each new agent tab from its first
	 *  prompt; `false` leaves the default `Agent N` name in place.
	 */
	enabled?: boolean,
	/**
	 *  Which model generates titles, as a tagged id:
	 *    `"claude:<flag>"`        → `claude -p --model <flag>` (empty flag = default)
	 *    `"opencode:<prov>/<id>"` → a one-shot OpenCode turn with that model
	 *    `"codex:<id>"`           → a one-shot ephemeral Codex turn
	 *  `None`/absent follows the default harness — see
	 *  [`TabTitleSettings::effective_model`].
	 */
	model?: string | null,
};

/**  How multiple `tags` filters combine. */
export type TagMode = "and" | "or";

/**  One streamed terminal event. Output is base64 because PTY output is binary. */
export type TerminalEvent = { kind: "output"; data: string } | { kind: "exited"; code: number | null };

/**  A library query: filters AND across fields, OR within a field. */
export type ThoughtQuery = {
	text?: string | null,
	types?: string[],
	statuses?: string[],
	projects?: string[],
	scopes?: string[],
	authors?: string[],
	tags?: string[],
	tagMode?: TagMode,
	/**  Inclusive lexicographic bounds against `fm.date` (ISO dates sort). */
	dateFrom?: string | null,
	dateTo?: string | null,
	sort?: SortKey,
	limit?: number | null,
	offset?: number | null,
};

/**
 *  The thoughts index changed: docs were (re)indexed, removed, or the whole
 *  tree was rescanned. `ids` are absolute-path doc ids (empty on rescans).
 *  Open editors use this to detect external changes to their document.
 */
export type ThoughtsIndexUpdated = {
	kind: string,
	ids: string[],
};

/**
 *  Probe of the default `~/thoughts` location, so the wizard can pick a sensible
 *  initial mode: if it's already a git repo, default to "open from disk" and
 *  prefill the path; otherwise default to "create" at the same path.
 */
export type ThoughtsProbe = {
	/**  Absolute `~/thoughts` path (tilde expanded), for prefilling the field. */
	defaultPath: string,
	/**  Whether that path exists on disk. */
	exists: boolean,
	/**  Whether it's already a git repository. */
	isGitRepo: boolean,
};

/**
 *  One selectable thoughts destination: the default backend (`name: None`) or
 *  a named profile.
 */
export type ThoughtsProfile = {
	/**  Profile name; `None` is the default backend (mapped without `--profile`). */
	name: string | null,
	backendKind: string,
	/**
	 *  Thoughts root as written in config (tilde kept, e.g. `~/thoughts`), for
	 *  display; None for backends without a filesystem tree (notion, anytype).
	 */
	thoughtsRepo: string | null,
	reposDir: string | null,
	globalDir: string | null,
	/**
	 *  Existing folder names under `<root>/<reposDir>` — the "existing folder"
	 *  choices for the dialog's folder select.
	 */
	folders: string[],
	/**
	 *  Why `folders` couldn't be read (e.g. permission denied), when the tree
	 *  exists but is inaccessible. An unreadable tree must not masquerade as
	 *  an empty one — the dialog surfaces this next to the folder select.
	 */
	foldersError: string | null,
};

export type ThoughtsRepoStatus = {
	branch: string | null,
	/**  Working-tree entries that differ from HEAD (staged + unstaged + untracked). */
	dirty: number,
	ahead: number,
	behind: number,
	hasRemote: boolean,
};

/**  How the user wants to set up their thoughts repository. */
export type ThoughtsSource = 
/**
 *  Clone a remote git repository (e.g. a private GitHub thoughts repo).
 *  `location` is where the clone is placed.
 *  When None, defaults to `~/thoughts`.
 */
{ mode: "clone"; url: string; 
/**
 *  Absolute path where the cloned repo will be placed.
 *  When None, defaults to `~/thoughts`.
 */
location: string | null } | 
/**  Use an existing local git repository. */
{ mode: "disk"; 
/**  Absolute path to the existing git repository. */
path: string } | 
/**  Initialise a fresh git repository at the given path. */
{ mode: "create"; 
/**  Absolute path where the new repo will be created. */
path: string };

export type Workstream = {
	id: string,
	projectPath: string,
	title: string,
	slug: string,
	branch: string,
	worktreePath: string,
	baseBranch: string,
	worktreeMode: WorktreeMode,
	stage: Stage,
	status: WorkstreamStatus,
	prNumber: number | null,
	createdAt: number | null,
	updatedAt: number | null,
	archivedAt: number | null,
};

/**
 *  Branch choices for the "new workstream" dialog. `branches` (local + remote)
 *  feeds the isolated base picker; `local_branches` feeds the existing/in-place
 *  pickers (a remote ref would detach HEAD); `current_branch` is the in-place default.
 */
export type WorkstreamBases = {
	branches: string[],
	localBranches: string[],
	defaultBase: string,
	currentBranch: string | null,
};

export type WorkstreamDoc = {
	workstreamId: string,
	docPath: string,
	/**  research | plan | other */
	role: string,
};

/**
 *  Whether a workstream is live or archived. Unknown stored values read as
 *  `Active` via [`WorkstreamStatus::parse`] (they can only come from a newer
 *  schema; showing the row beats hiding it).
 */
export type WorkstreamStatus = "active" | "archived";

export type WorkstreamView = {
	item: Workstream,
	git: WorktreeStatus,
	/**  Set only by `create_workstream`: report of copied untracked files; `null` elsewhere. */
	seed: SeedReport | null,
};

/**
 *  A workstream's worktree changed on disk — a file edit, or git's index/HEAD
 *  moved (`git add`/`commit`/`checkout`, incl. mid-turn). The backend watches
 *  the active worktree and its git dir (`commands::workstreams::watch_worktree`)
 *  and emits this so the Changes panel + git status refresh live. The frontend
 *  refetches that workstream's worktree-git queries (see `invalidateWorktreeGit`).
 */
export type WorktreeChanged = {
	workstreamId: string,
};

/**  A worktree file's text + mtime (the save concurrency token). */
export type WorktreeFile = {
	content: string,
	mtimeMs: number | null,
};

/**
 *  A worktree's working state split the way the panel renders it: what's in the
 *  index (staged) vs. what differs between index and working tree (unstaged). A
 *  partially-staged file legitimately appears in both lists.
 */
export type WorktreeGitStatus = {
	staged: GitFileEntry[],
	unstaged: GitFileEntry[],
};

/**
 *  How a workstream is backed: `isolated` (app-created branch + dedicated
 *  worktree), `existing` (user's local branch in a dedicated worktree),
 *  `inplace` (no worktree — the project's own checkout), or `folder` (a
 *  [`ProjectSource::Folder`](super::ProjectSource) project — the project
 *  directory itself, with no git at all). Governs whether the branch +
 *  directory are app-owned and safe to drop on archive/delete.
 * 
 *  Tolerance: an unrecognized stored value reads (via [`WorktreeMode::parse`])
 *  as `Inplace` — the touch-nothing mode — so a mangled row can never make
 *  archive/cleanup delete a branch or checkout the app doesn't own.
 */
export type WorktreeMode = "isolated" | "existing" | "inplace" | "folder";

export type WorktreeStatus = {
	exists: boolean,
	branch: string | null,
	/**  Tracked changes (staged + unstaged), excluding thoughts/. */
	dirty: number,
	/**  Added lines in the working-tree diff vs HEAD, excluding thoughts/. */
	additions: number,
	/**  Deleted lines in the working-tree diff vs HEAD, excluding thoughts/. */
	deletions: number,
	/**  Untracked files, excluding thoughts/ (informational only). */
	untracked: number,
	/**
	 *  Commits ahead/behind the upstream once it exists, else the base branch.
	 *  Drops to 0 the moment the branch is pushed — a sync indicator, not a
	 *  "has work to ship" signal (see `ahead_of_base`).
	 */
	ahead: number,
	behind: number,
	/**
	 *  Commits on this branch not yet in the base branch (the PR's merge
	 *  target), always measured against `base_branch` regardless of the
	 *  upstream. Unlike `ahead`, this does NOT drop to 0 when the branch is
	 *  pushed, so it answers "is there anything to open a PR for?" — the signal
	 *  Ship gates on.
	 */
	aheadOfBase: number,
	thoughts: LinkStatus,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

